"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[13744],{13744:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-murder-of-roger-ackroyd.png\\"\\n          title=\\"The Murder of Roger Ackroyd\\"\\n          author=\\"Agatha Christie\\"\\n          publisher=\\"Golden Bough\\"\\n          publishedDate=\\"2013-05-27\\"\\n          isbn=\\"9788982737053\\"\\n          rating=4\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\nIt is said that the way the story unfolded was fresh at the time, rather than the story itself.  \\nWhile this type of narrative trick might not be surprising today, it is said to have surprised both readers and critics back then.  \\n<mark>Arthur Conan Doyle</mark> even admired this work.  \\n<br>\\nSince then, many works using the device of the ```unreliable narrator``` have emerged, and the prevailing opinion is that this work is the origin of it.  \\n"}')}}]);